def recommend_platform(technical_skill, customization_need, integration_need):
    if technical_skill <= 2 and customization_need <= 2 and integration_need <= 2:
        return "No Code"
    elif technical_skill <= 4 and customization_need <= 4:
        return "Low Code"
    else:
        return "Traditional Code"

cases = pd.DataFrame({
    "case": ["活動報名表", "CRM 與 ERP 串接", "銀行核心交易系統"],
    "technical_skill": [1, 3, 5],
    "customization_need": [1, 4, 5],
    "integration_need": [1, 4, 5]
})

cases["recommendation"] = cases.apply(
    lambda row: recommend_platform(row["technical_skill"], row["customization_need"], row["integration_need"]),
    axis=1
)

print(cases)
